mapper.select:
SELECT OQ.*
FROM shopwizard.tOrdOrderQuot OQ

    AND OQ.QuotNo = #{pQuotNo}
    AND OQ.ChnlName = #{pChnlName}
    AND OQ.DealName = #{pDealName}
    AND OQ.DealNo = #{pDealNo}


            AND OQ.MatchProdCode = #{pMatchProdCode}
            AND OQ.MatchProdCode LIKE CONCAT('%',#{pMatchProdCode},'%')


    AND OQ.ShopCode = #{pShopCode}
    AND OQ.ProdCode = #{pProdCode}
    AND OQ.ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND OQ.OptionName LIKE CONCAT('%',#{pOptionName},'%')

         AND (OQ.RegistDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND OQ.RegistDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY)) 


LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdOrderQuot OQ

    AND OQ.QuotNo = #{pQuotNo}
    AND OQ.ChnlName = #{pChnlName}
    AND OQ.DealName = #{pDealName}
    AND OQ.DealNo = #{pDealNo}


            AND OQ.MatchProdCode = #{pMatchProdCode}
            AND OQ.MatchProdCode LIKE CONCAT('%',#{pMatchProdCode},'%')


    AND OQ.ShopCode = #{pShopCode}
    AND OQ.ProdCode = #{pProdCode}
    AND OQ.ProdName LIKE CONCAT('%',#{pProdName},'%')
    AND OQ.OptionName LIKE CONCAT('%',#{pOptionName},'%')

SELECT * FROM shopwizard.tOrdOrderQuot

    AND ChnlName = #{pChnlName}
    AND DealName = #{pDealName}
    AND DealNo = #{pDealNo}
    AND MatchProdCode = #{pMatchProdCode}
